import React, { useState } from "react";
import axios from "axios";
import {
  Box,
  Paper,
  TextField,
  Button,
  Typography,
  Alert,
  CircularProgress,
  Tabs,
  Tab,
  InputAdornment,
  IconButton,
} from "@mui/material";
import RestaurantIcon from "@mui/icons-material/Restaurant";
import Visibility from "@mui/icons-material/Visibility";
import VisibilityOff from "@mui/icons-material/VisibilityOff";


const AuthPage = ({ onLogin }) => {
  const [tab, setTab] = useState(0);

  const [loginData, setLoginData] = useState({
    mobile: "",
    password: "",
  });

  const [registerData, setRegisterData] = useState({
    name: "",
    mobile: "",
    password: "",
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [showLoginPassword, setShowLoginPassword] = useState(false);
  const [showRegisterPassword, setShowRegisterPassword] = useState(false);
  const handleLoginChange = (e) => {
    setLoginData({
      ...loginData,
      [e.target.name]: e.target.value,
    });
  };

  const handleRegisterChange = (e) => {
    setRegisterData({
      ...registerData,
      [e.target.name]: e.target.value,
    });
  };

  // LOGIN
  const handleLogin = async (e) => {
    e.preventDefault();

    try {
      setLoading(true);
      setError("");
      setSuccess("");

      const response = await axios.post("/api/auth/login", loginData);

      const { token, user } = response.data;

      // Save authentication data
      localStorage.setItem("token", token);
      localStorage.setItem("user", JSON.stringify(user));

      // Add token to future Axios requests
      axios.defaults.headers.common["Authorization"] = `Bearer ${token}`;

      setSuccess("Login successful!");

      // Send logged-in user to App
      onLogin(user);
    } catch (error) {
      console.error("Login error:", error);

      setError(
        error.response?.data?.message ||
          "Login failed. Please check your credentials."
      );
    } finally {
      setLoading(false);
    }
  };

  // REGISTER
  const handleRegister = async (e) => {
    e.preventDefault();

    try {
      setLoading(true);
      setError("");
      setSuccess("");

      const response = await axios.post(
        "/api/auth/register",
        registerData
      );

      setSuccess(
        response.data.message +
          ". You can now login."
      );

      // Clear registration form
      setRegisterData({
        name: "",
        mobile: "",
        password: "",
      });

      // Automatically switch to login
      setTab(0);
    } catch (error) {
      console.error("Registration error:", error);

      setError(
        error.response?.data?.message ||
          "Registration failed. Please try again."
      );
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box
      sx={{
        minHeight: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        background:
          "linear-gradient(135deg, #E8F5E9 0%, #F1F8E9 50%, #FFF3E0 100%)",
        p: 2,
      }}
    >
      <Paper
        elevation={10}
        sx={{
          width: "100%",
          maxWidth: 450,
          borderRadius: 4,
          overflow: "hidden",
        }}
      >
        {/* Header */}
        <Box
          sx={{
            background:
              "linear-gradient(135deg, #2E7D32 0%, #4CAF50 100%)",
            color: "white",
            textAlign: "center",
            py: 4,
            px: 3,
          }}
        >
          <RestaurantIcon sx={{ fontSize: 55, mb: 1 }} />

          <Typography
            variant="h4"
            sx={{ fontWeight: 800 }}
          >
            CanteenPro
          </Typography>

          <Typography
            variant="body1"
            sx={{ opacity: 0.9, mt: 1 }}
          >
            Smart Food Ordering System
          </Typography>
        </Box>

        {/* Tabs */}
        <Tabs
          value={tab}
          onChange={(event, newValue) => {
            setTab(newValue);
            setError("");
            setSuccess("");
          }}
          centered
          variant="fullWidth"
        >
          <Tab label="Login" />
          <Tab label="Register" />
        </Tabs>

        <Box sx={{ p: 4 }}>
          {error && (
            <Alert
              severity="error"
              sx={{ mb: 2 }}
            >
              {error}
            </Alert>
          )}

          {success && (
            <Alert
              severity="success"
              sx={{ mb: 2 }}
            >
              {success}
            </Alert>
          )}

          {/* LOGIN */}
          {tab === 0 && (
            <Box
              component="form"
              onSubmit={handleLogin}
            >
              <Typography
                variant="h5"
                sx={{
                  fontWeight: 700,
                  mb: 3,
                  color: "#2E7D32",
                }}
              >
                Welcome Back
              </Typography>

              <TextField
                fullWidth
                label="Mobile Number"
                name="mobile"
                value={loginData.mobile}
                onChange={handleLoginChange}
                required
                inputProps={{
                    maxLength: 10,
                    inputMode: "numeric",
                }}
                sx={{ mb: 2 }}
              />
              <TextField
                fullWidth
                label="Password"
                name="password"
                type={showLoginPassword ? "text" : "password"}
                value={loginData.password}
                onChange={handleLoginChange}
                required
                sx={{ mb: 3 }}
                InputProps={{
                    endAdornment: (
                    <InputAdornment position="end">
                        <IconButton
                        onClick={() =>
                            setShowLoginPassword(!showLoginPassword)
                        }
                        edge="end"
                        >
                        {showLoginPassword ? (
                            <VisibilityOff />
                        ) : (
                            <Visibility />
                        )}
                        </IconButton>
                    </InputAdornment>
                    ),
                }}
                />

              <Button
                type="submit"
                fullWidth
                variant="contained"
                size="large"
                disabled={loading}
                sx={{
                  py: 1.5,
                  borderRadius: 2,
                  fontWeight: 700,
                  background:
                    "linear-gradient(135deg, #2E7D32, #4CAF50)",
                }}
              >
                {loading ? (
                  <CircularProgress
                    size={25}
                    color="inherit"
                  />
                ) : (
                  "Login"
                )}
              </Button>
            </Box>
          )}

          {/* REGISTER */}
          {tab === 1 && (
            <Box
              component="form"
              onSubmit={handleRegister}
            >
              <Typography
                variant="h5"
                sx={{
                  fontWeight: 700,
                  mb: 3,
                  color: "#2E7D32",
                }}
              >
                Create Account
              </Typography>

              <TextField
                fullWidth
                label="Full Name"
                name="name"
                value={registerData.name}
                onChange={handleRegisterChange}
                required
                sx={{ mb: 2 }}
              />

              <TextField
                fullWidth
                label="Mobile Number"
                name="mobile"
                value={registerData.mobile}
                onChange={handleRegisterChange}
                required
                inputProps={{
                    maxLength: 10,
                    inputMode: "numeric",
                }}
                sx={{ mb: 2 }}
              />

              <TextField
                fullWidth
                label="Password"
                name="password"
                type={showRegisterPassword ? "text" : "password"}
                value={registerData.password}
                onChange={handleRegisterChange}
                required
                autoComplete="new-password"
                helperText="Password must contain at least 6 characters"
                sx={{ mb: 3 }}
                InputProps={{
                    endAdornment: (
                    <InputAdornment position="end">
                        <IconButton
                        onClick={() =>
                            setShowRegisterPassword(!showRegisterPassword)
                        }
                        edge="end"
                        >
                        {showRegisterPassword ? (
                            <VisibilityOff />
                        ) : (
                            <Visibility />
                        )}
                        </IconButton>
                    </InputAdornment>
                    ),
                }}
                />

              <Button
                type="submit"
                fullWidth
                variant="contained"
                size="large"
                disabled={loading}
                sx={{
                  py: 1.5,
                  borderRadius: 2,
                  fontWeight: 700,
                  background:
                    "linear-gradient(135deg, #2E7D32, #4CAF50)",
                }}
              >
                {loading ? (
                  <CircularProgress
                    size={25}
                    color="inherit"
                  />
                ) : (
                  "Create Account"
                )}
              </Button>
            </Box>
          )}
        </Box>
      </Paper>
    </Box>
  );
};

export default AuthPage;
